// Basic Pointer Declaration and Dereference
int value = 42;
int* ptr = &value; // Take address
*ptr = 100;        // Dereference (modify value)
int read_val = *ptr;

// Array Decay and Pointer Arithmetic
int arr[5] = {1, 2, 3, 4, 5};
int* p_arr = arr;       // arr decays to &arr[0]
int third = *(p_arr + 2); // Pointer arithmetic
int also_third = p_arr[2]; // Equivalent array syntax

// Dynamic Memory (C Style)
int N = 10;
int* c_ptr = malloc(N * sizeof(int));
if (c_ptr) c_ptr[0] = N;
free(c_ptr);

// Dynamic Memory (C++ Style)
size_t S = 20;
int* cpp_ptr = new int[S];
cpp_ptr[S - 1] = 0;
delete[] cpp_ptr; // Must use delete[] for arrays
